            "connect cannot be called on a datagram socket",
        ));
    }

    let addr = socket2::SockAddr::unix(path)?;
    if let Err(err) = self.inner.connect(&addr) {
        if err.raw_os_error() != Some(libc::EINPROGRESS) {
